import React from 'react'
import { connect } from 'react-redux'
import moment from 'moment-timezone'
import {
  Table,
  Card,
  Button,
  Modal
} from 'antd'
import PropTypes from 'prop-types'

import NotificationsTraceWrapper from './index.style'
import NotificationActions from '../../../redux/notifications/actions'

const { getNotificationsTrace } = NotificationActions

class NotificationsTrace extends React.Component {
  state = {
    emailContentPopUp: false,
    modalEmailContent: null
  }
  columnsNotifications = [
    {
      title: 'Event',
      dataIndex: 'event',
      key: 'event'
    }, {
      title: 'Action group name',
      dataIndex: 'action_group_name',
      key: 'action_group_name'
    }, {
      title: 'Notification type',
      dataIndex: 'notification_type',
      key: 'notification_type'
    }, {
      title: 'Status',
      dataIndex: 'status',
      key: 'status'
    }, {
      title: 'Remark',
      dataIndex: 'remark',
      key: 'remark'
    }, {
      title: 'Recipient',
      dataIndex: 'recipient',
      key: 'recipient'
    }, {
      title: 'Subject',
      dataIndex: 'subject',
      key: 'subject'
    }, {
      title: 'Created At',
      dataIndex: 'created_at',
      key: 'created_at',
      render: val => (moment(val).add(7, 'hours').format('DD MMMM YYYY HH:mm:ss'))
    }, {
      title: 'Updated At',
      dataIndex: 'updated_at',
      key: 'updated_at',
      render: val => (moment(val).add(7, 'hours').format('DD MMMM YYYY HH:mm:ss'))
    }, {
      title: 'Content',
      dataIndex: 'content',
      render: (val) => [null, ''].indexOf(val) !== -1
        ? '-'
        : <span className='anchor' onClick={() => this.showEmailModal(val)}>View</span>,
      key: 'content'
    }
    // to be enabled in future release
    // {
    //   title: 'Action',
    //   dataIndex: 'delivery_id',
    //   key: 'delivery_id',
    //   render: (val, record) => (
    //     <Button
    //       disabled={!['ERROR_IN_PROCESSING', 'NOT_SENT', 'ERROR_IN_SENDING', 'ERROR_IN_DELIVERY'].includes(record.status)}
    //       type='primary'
    //       onClick={() => this.retriggerNotification(val, record)}
    //     >
    //       Resend
    //     </Button>
    //   ),
    //   align: 'center'
    // }
  ]

  componentDidMount () {
    this.props.getNotificationsTrace({ params: this.props.match.params })
  }

  onBackNotifications = () => {
    const { history } = this.props
    if (history) {
      const { action } = history
      if (action === 'POP') {
        history.push('/notifications')
      } else {
        history.goBack()
      }
    }
  }

  showEmailModal = (modalEmailContent) => {
    this.setState({ emailContentPopUp: true, modalEmailContent })
  }

  closeModal = () => {
    this.setState({ emailContentPopUp: false })
  }

  render () {
    const {
      notificationsTrace
    } = this.props
    const {
      emailContentPopUp,
      modalEmailContent
    } = this.state
    return (
      <NotificationsTraceWrapper>
        <Modal
          title='Content'
          visible={emailContentPopUp}
          onOk={this.closeModal}
          onCancel={this.closeModal}
          width='100%'
          bodyStyle={{
            height: '75vh'
          }}
        >
          <iframe width='100%' height='100%' srcDoc={modalEmailContent} title='Email Content' />
        </Modal>
        <Card>
          <Button onClick={this.onBackNotifications}>
            Back
          </Button>
          <Table
            scroll={{ x: true }}
            pagination={{
              pageSize: 1000
            }}
            columns={this.columnsNotifications}
            dataSource={notificationsTrace}
          />
        </Card>
      </NotificationsTraceWrapper>
    )
  }
}

NotificationsTrace.propTypes = {
  notificationsTrace: PropTypes.array.isRequired
}

NotificationsTrace.defaultProps = {
  notificationsTrace: []
}

export default connect(
  state => ({
    notificationsTrace: state.Notifications.notificationsTrace,
    notificationsTraceMsg: state.Notifications.notificationsTraceMsg,
    getNotificationsTraceLoading: state.Loading.GET_NOTIFICATIONS_TRACE,
    getNotificationsTraceError: state.Error.GET_NOTIFICATIONS_TRACE
  }),
  {
    getNotificationsTrace
  }
)(NotificationsTrace)
